const j = $input.first().json;
const act_id = j.act_id || j.meta_ad_account_id || '';
const campaign_id = j.campaign_id || null;
if (!act_id || !act_id.startsWith('act_')) return [{ json: { error: 'act_id requerido' } }];
return [{ json: { act_id, campaign_id } }];

const items = $input.all();
let ads = [];
for (const it of items) {
  const j = it.json;
  if (j.error) continue;
  const data = Array.isArray(j.data) ? j.data : [j];
  ads = ads.concat(data);
}
const problematic = ads.filter(a => {
  const status = (a.effective_status || a.status || '').toLowerCase();
  const feedback = a.ad_review_feedback;
  return status === 'rejected' || status === 'pending_review' || (feedback && Object.keys(feedback).length > 0);
});
const output = { total: ads.length, problematic_count: problematic.length, ads: problematic.map(a => ({ id: a.id, name: a.name, status: a.effective_status || a.status, feedback: a.ad_review_feedback || null })) };
return [{ json: { output: JSON.stringify(output, null, 2) } }];
